RSpec.describe Timekeeping::Gateway do
  let(:replay_company) { create(:company) }
  let(:replay_admin) do
    create(:user, current_workspace_id: replay_company.id).tap do |user|
      create(:employment, company: replay_company, user:)
      user.add_role :admin, replay_company
    end
  end
  let(:replay_project) { create(:project, billable: true, client: create(:client, company: replay_company)) }
  let(:replay_foreign_company) { create(:company) }
  let(:replay_foreign_admin) do
    create(:user, current_workspace_id: replay_foreign_company.id).tap do |user|
      create(:employment, company: replay_foreign_company, user:)
      user.add_role :admin, replay_foreign_company
    end
  end
  let(:replay_base_url) { "http://timekeeping.test" }
  let(:replay_fake) { TimekeepingContract::FakeTimekeeping.new(token_public_key: timekeeping_key_pair.public_key) }

  before { route_timekeeping_to_fake(replay_fake, base_url: replay_base_url) }

  def replay_gateway(company:, actor:, request_id:)
    described_class.new(
      context: Timekeeping::WriteContext.new(company:, actor:, actor_kind: "user", request_id:),
      write_client: Timekeeping::EntryWriteClient.new(base_url: replay_base_url),
      read_client: Timekeeping::EntryApiClient.new(base_url: replay_base_url)
    )
  end

  it "replays a committed Timekeeping delete for the deleting company only, and another company reusing the request id gets not found" do
    TimekeepingOwnership.find(TimekeepingOwnership::SINGLETON_ID).update_columns(owner: "timekeeping", generation: 2)
    replay_fake.generation = 2
    replay_fake.register_company(id: replay_company.id, edit_days: replay_company.timesheet_edit_days)
    replay_fake.register_user(id: replay_admin.id, company_id: replay_company.id, role: "admin")
    replay_fake.register_project(id: replay_project.id, company_id: replay_company.id)
    replay_fake.register_company(id: replay_foreign_company.id, edit_days: replay_foreign_company.timesheet_edit_days)
    replay_fake.register_user(id: replay_foreign_admin.id, company_id: replay_foreign_company.id, role: "admin")
    entry_id = replay_fake.add_entry(company_id: replay_company.id, user_id: replay_admin.id,
                                     project_id: replay_project.id, work_date: Date.current.iso8601).fetch("id")
    allow_all = ->(_entry) { }

    with_timekeeping_env(Timekeeping::UserToken::PRIVATE_KEY_ENV, timekeeping_key_pair.to_pem) do
      owner_gateway = replay_gateway(company: replay_company, actor: replay_admin, request_id: "req-replay-tenant")
      expect(owner_gateway.destroy(entry_id:, authorize: allow_all)).to be(true)
      version_after_delete = replay_fake.stored_entry(entry_id).fetch("version")

      # "A retry of a committed delete cannot reach Timekeeping's stored answer."
      # The same company and actor, with the same request id, reach the stored answer.
      expect(owner_gateway.destroy(entry_id:, authorize: allow_all)).to be(true)

      # "Address this in follow-up design work with an authenticated replay path; do not treat every missing entry as a successful delete."
      # A user of another company who reuses the request id and entry id derives the same key, but must get not found.
      requests_before_foreign = replay_fake.requests.size
      foreign_gateway = replay_gateway(company: replay_foreign_company, actor: replay_foreign_admin,
                                       request_id: "req-replay-tenant")
      expect { foreign_gateway.destroy(entry_id:, authorize: allow_all) }.to raise_error(ActiveRecord::RecordNotFound)

      foreign_requests = replay_fake.requests.drop(requests_before_foreign)
      expect(foreign_requests).not_to be_empty
      expect(foreign_requests.pluck(:path))
        .to all(start_with("/v1/companies/#{replay_foreign_company.id}/"))
      expect(replay_fake.stored_entry(entry_id).fetch("version")).to eq(version_after_delete)
    end
  end
end

