  end

  before do
    route_timekeeping_to_fake(rp_fake, base_url: rp_base_url)
    TimekeepingOwnership.find(TimekeepingOwnership::SINGLETON_ID).update_columns(owner: "timekeeping", generation: 2)
    rp_fake.generation = 2
    rp_fake.register_company(id: rp_company.id, edit_days: rp_company.timesheet_edit_days)
    rp_fake.register_project(id: rp_project.id, company_id: rp_company.id)
  end

  around do |example|
    with_timekeeping_env(Timekeeping::UserToken::PRIVATE_KEY_ENV, timekeeping_key_pair.to_pem) { example.run }
  end

  # "Replaying it needs a separate design that keeps the lookup-then-authorize order, and nothing is deleted twice meanwhile."
  # The lookup hides a colleague's entry from scope :actor while it is still kept. The fallback DELETE must not discard it,
  # because Timekeeping's own destroy would let an admin delete it without the gateway's scope or policy.
  it "answers not found for a kept colleague entry outside scope actor and the replay-only delete it sends discards nothing" do
