    expect(deletes.size).to eq(1)
    expect(deletes.first[:headers]["Idempotency-Replay"]).to eq("only")
    expect(deletes.first[:headers]["If-Match"]).to eq("replay-only")
    expect(rp_fake.stored_entry(entry_id)["discarded_at"]).to be_nil
    expect(rp_fake.stored_entry(entry_id)["version"]).to eq(1)
