  let(:rp_company) { create(:company) }
  let(:rp_project) { create(:project, billable: true, client: create(:client, company: rp_company)) }
  let(:rp_base_url) { "http://timekeeping.test" }
  let(:rp_fake) { TimekeepingContract::FakeTimekeeping.new(token_public_key: timekeeping_key_pair.public_key) }
  let(:rp_allow_all) { ->(_entry) { } }

  def rp_admin
    create(:user, current_workspace_id: rp_company.id).tap do |user|
      create(:employment, company: rp_company, user:)
      user.add_role :admin, rp_company
      rp_fake.register_user(id: user.id, company_id: rp_company.id, role: "admin")
    end
  end

  def rp_gateway(actor, request_id)
    context = Timekeeping::WriteContext.new(company: rp_company, actor:, actor_kind: "user", request_id:)
    described_class.new(context:, write_client: Timekeeping::EntryWriteClient.new(base_url: rp_base_url),
                        read_client: Timekeeping::EntryApiClient.new(base_url: rp_base_url))
  end

  before do
    route_timekeeping_to_fake(rp_fake, base_url: rp_base_url)
    TimekeepingOwnership.find(TimekeepingOwnership::SINGLETON_ID).update_columns(owner: "timekeeping", generation: 2)
    rp_fake.generation = 2
    rp_fake.register_company(id: rp_company.id, edit_days: rp_company.timesheet_edit_days)
    rp_fake.register_project(id: rp_project.id, company_id: rp_company.id)
  end

  around do |example|
    with_timekeeping_env(Timekeeping::UserToken::PRIVATE_KEY_ENV, timekeeping_key_pair.to_pem) { example.run }
  end

  # "Address this in follow-up design work with an authenticated replay path; do not treat every missing entry as a successful delete."
  # A new request id derives a new Idempotency-Key, so no receipt matches and the entry being gone is not a success.
  it "answers not found when a committed delete is retried under a new request id, sending a different key and discarding nothing more" do
    admin = rp_admin
    entry_id = rp_fake.add_entry(company_id: rp_company.id, user_id: admin.id, project_id: rp_project.id,
